	cmpTemp := g.newTemp()
	g.emit(Instruction{
		Op:   OpLt,
		Dest: cmpTemp,
		Src1: Operand{Name: iterName},
		Src2: endOp,
	})

	// Jump if false (exit loop)
	g.emit(Instruction{
		Op:    OpJumpIfFalse,
		Src1:  cmpTemp,
		Label: endLabel,
	})

