// genBinaryExpr generates IR for a binary expression
func (g *Generator) genBinaryExpr(node *ast.Node) (Operand, error) {
	if len(node.Children) < 2 {
		return Operand{}, fmt.Errorf("binary expression requires 2 operands")
	}

