	result := g.newTemp()
	g.emit(Instruction{
		Op:   OpCall,
		Dest: result,
		Fn:   fnName,
	})

	return result, nil
}

// Helper functions

func (g *Generator) newTemp() Operand {
	temp := Operand{
		IsTemp: true,
		Name:   fmt.Sprintf("t%d", g.tempCount),
	}
	g.tempCount++
	return temp
}

func (g *Generator) newLabel(prefix string) string {
	label := fmt.Sprintf("L_%s_%d", prefix, g.labelCount)
