	if p.curToken.Type != ast.TokenIdent {
		return nil, fmt.Errorf("expected field name")
	}

	fieldNode := &ast.Node{
		Kind:  ast.NodeFieldDecl,
		Value: p.curToken.Value,
		Line:  p.curToken.Line,
