		Kind:  ast.NodeIdent,
		Value: p.curToken.Value,
		Line:  p.curToken.Line,
		Col:   p.curToken.Col,
	}
	fieldNode.Children = append(fieldNode.Children, typeNode)

	p.nextToken() // consume type

	return fieldNode, nil
}

