func (s *Scope) lookup(name string) (TypeInfo, bool) {
	if t, exists := s.vars[name]; exists {
		return t, true
	}
	if s.parent != nil {
		return s.parent.lookup(name)
	}
	return UnknownType, false
}

// StructDef represents a struct definition
